head.script:

scwin.onpageload = function() {

};

scwin.onpageunload = function() {

};

scwin.autoComplete1_oneditenter = function() {
	console.log("Enter key pressed.");
};

scwin.spinner_oneditenter = function() {
	localStorage.setItem("log", "Spinner Onedienter");	
	console.log("Spinner Onedienter");
};

scwin.simulateWrapper = function(target, type, options) {
	WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate2 = function() {
	scwin.simulateWrapper('#spinner___input', 'key-combo', {
		combo: 'ENTER'
	});
}
scwin.setSimulate1 = function() {
	scwin.simulateWrapper('#spinner___input', 'key-sequence', {
		sequence: '1'
	});
}	
scwin.checkVal = function() {
	return WebSquare.wUnit.getJq("#wq_uuid_4_cell_0_2").hasClass('focusedTd');
}	
scwin.checkVal = function() {
	return localStorage.getItem('log') == 'Spinner Onedienter';
}
scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('spinner___input').focus()");
	WebSquare.wUnit.addCommand("pause", "400");		
	//WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('spinner___input').click()");
	WebSquare.wUnit.addCommand("pause", "400");		

	WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
	WebSquare.wUnit.addCommand("pause", "500");

	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");
	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}	
scwin.unitTest()
localStorage.removeItem("log");
